          { t: "wahl", f: "Wer unterzeichnete den Zwei-plus-Vier-Vertrag 1990?", a: ["Bundesrepublik und DDR sowie USA, Sowjetunion, Großbritannien und Frankreich", "Alle Mitglieder der NATO", "Bundesrepublik, DDR, Polen und Österreich", "Nur die Bundesrepublik und die Sowjetunion"], r: 0, info: "Der Vertrag gab Deutschland die volle Souveränität zurück und bestätigte die Oder-Neiße-Grenze." },
          { t: "wahl", f: "Welches Datum ist der Tag der Deutschen Einheit?", a: ["3. Oktober 1990", "9. November 1989", "1. Juli 1990", "17. Juni 1953"], r: 0, info: "Am 3. Oktober 1990 trat die DDR nach Artikel 23 dem Geltungsbereich des Grundgesetzes bei." },
          { t: "reihenfolge", f: "Bringe die Ereignisse in die richtige Reihenfolge", items: ["1962: Kubakrise", "1970: Kniefall von Warschau", "1975: KSZE-Schlussakte von Helsinki", "1985: Gorbatschow wird Generalsekretär", "1989: Fall der Mauer", "1990: Deutsche Einheit"] },
          { t: "karte", vorne: "Entspannungspolitik", hinten: "Politik, die Spannungen zwischen Ost und West durch Verträge, Gespräche und Zusammenarbeit abbauen will", bsp: "Brandts Motto lautete „Wandel durch Annäherung“." }
