  // ---------- Erdkunde ----------
  const E = fach("erdkunde");
  if (E) {
    E.buch = BUCH;
    kap(E, "disparitaeten", K[5]);
    kap(E, "klima", K[6]);
    kap(E, "tropen", K[6]);
    kap(E, "stadt", K[7]);
    kap(E, "globalisierung", K[9]);
    kap(E, "bevoelkerung", K[10]);
    E.themen.push(
      {
        id: "klimafolgen",
        kapitel: K[6],
        titel: "Klimawandel: Folgen und Klimaschutz-Abkommen",
        kurz: "Treibhausgase, Meeresspiegel, Permafrost, Arktis, Hochwasser 2021, Anpassung vs. Klimaschutz, Kyoto, Paris, Klimaneutralität 2045",
        erklaerung: "<p>Das Klima hat sich über Jahrmillionen immer verändert – heute aber ungewöhnlich schnell und vom Menschen verursacht: Beim Verbrennen von Kohle, Öl und Gas entsteht <b>CO2</b>, das den natürlichen Treibhauseffekt verstärkt. Die Erde hat sich seit vorindustrieller Zeit um rund 1,2 Grad erwärmt.</p><p>Folgen: mehr <b>Wetterextreme</b> (Hitze, Dürre, Starkregen wie beim Ahrtal-Hochwasser 2021), Schmelzen von Gletschern und Eisschilden auf dem Festland, <b>Meeresspiegelanstieg</b> durch Schmelzwasser und Ausdehnung des warmen Wassers, eine sich doppelt so schnell erwärmende <b>Arktis</b> und tauende <b>Dauerfrostböden</b>, die Methan freisetzen. Gegenstrategien sind <b>Klimaschutz</b> (Ursachen verringern: erneuerbare Energien, Kohleausstieg) und <b>Anpassung</b> (mit Folgen leben: Deiche, Hitzeaktionspläne, Schwammstadt). International gelten das Kyoto-Protokoll (1997) und das Pariser Abkommen (2015: deutlich unter 2 Grad, möglichst 1,5 Grad). Deutschland will bis 2045 klimaneutral sein. Typischer Fehler: Schmelzendes Meereis lässt den Meeresspiegel nicht steigen – es schwimmt schon im Wasser. Entscheidend ist das Eis an Land.</p>",
        aufgaben: [
          { t: "wahl", f: "Welches Treibhausgas verursacht der Mensch mengenmäßig am meisten?", a: ["Kohlenstoffdioxid (CO2)", "Methan", "Lachgas", "Ozon"], r: 0, info: "CO2 entsteht vor allem beim Verbrennen von Kohle, Öl und Gas sowie bei der Zementherstellung." },
          { t: "zahl", f: "Um etwa wie viel Grad Celsius hat sich die Erde seit vorindustrieller Zeit erwärmt?", l: 1.2, tol: 0.3, einheit: "°C", info: "Der Wert liegt je nach Messreihe zwischen 1,1 und 1,3 Grad; 2024 war das erste Kalenderjahr über 1,5 Grad." },
          { t: "wahl", f: "Welches Ziel steht im Pariser Klimaabkommen von 2015?", a: ["Erwärmung deutlich unter 2 Grad halten, möglichst auf 1,5 Grad begrenzen", "Erwärmung bis 2100 auf 4 Grad begrenzen", "Alle Kohlekraftwerke bis 2020 abschalten", "Jedes Land pflanzt eine Milliarde Bäume"], r: 0, info: "Fast alle Staaten der Welt haben das Abkommen unterzeichnet; jedes Land legt eigene Klimaziele vor." },
          { t: "wahl", f: "Warum steigt der Meeresspiegel?", a: ["Landeis schmilzt und wärmeres Wasser dehnt sich aus", "Es regnet weltweit mehr", "Flüsse führen mehr Sand ins Meer", "Die Kontinente sinken ab"], r: 0, info: "Beide Ursachen sind etwa gleich wichtig; seit 1900 stieg der Meeresspiegel um rund 20 Zentimeter." },
          { t: "wahl", f: "Lässt schmelzendes Meereis in der Arktis den Meeresspiegel steigen?", a: ["Nein, es schwimmt bereits im Wasser und verdrängt es schon", "Ja, es ist die Hauptursache", "Ja, aber nur im Sommer", "Nur, wenn es salzig ist"], r: 0, info: "Gefährlich für den Meeresspiegel sind Gletscher und Eisschilde an Land, vor allem in Grönland und der Antarktis." },
          { t: "wahl", f: "Was passiert, wenn Dauerfrostböden (Permafrost) auftauen?", a: ["Gespeichertes Methan und CO2 werden frei und verstärken die Erwärmung", "Der Boden wird fruchtbarer und bindet mehr CO2", "Es entsteht neues Eis", "Nichts – der Boden bleibt stabil"], r: 0, info: "Das ist eine Rückkopplung: Die Erwärmung verursacht Vorgänge, die sie weiter antreiben. Außerdem sacken Häuser und Straßen ab." },
          { t: "wahl", f: "Warum erwärmt sich die Arktis schneller als der Rest der Erde?", a: ["Dunkles Wasser und Land nehmen mehr Sonnenwärme auf als helles Eis, das zurückstrahlt", "Weil die Sonne dort länger scheint", "Weil es dort mehr Vulkane gibt", "Weil mehr Schiffe fahren"], r: 0, info: "Man nennt das den Eis-Albedo-Effekt: Weniger Eis bedeutet weniger Rückstrahlung und noch mehr Erwärmung." },
          { t: "eingabe", f: "In welchem Jahr zerstörte ein Starkregen-Hochwasser das Ahrtal und Teile von NRW?", l: ["2021"], info: "Im Juli 2021 starben in Deutschland über 180 Menschen; der Schaden lag bei über 30 Milliarden Euro." },
          { t: "wahl", f: "Welche Folge des Klimawandels ist in Deutschland bereits spürbar?", a: ["Häufigere Hitzewellen, Dürren und Starkregen", "Ausbreitung von Gletschern in den Alpen", "Deutlich kältere Winter überall", "Mehr Schnee im Flachland"], r: 0, info: "Die Dürrejahre 2018 bis 2020 haben vielen Wäldern stark zugesetzt, besonders Fichten." },
          { t: "wahl", f: "Was ist der Unterschied zwischen Klimaschutz und Klimaanpassung?", a: ["Klimaschutz verringert die Ursachen, Anpassung bereitet auf die Folgen vor", "Klimaschutz ist Aufgabe der Städte, Anpassung Aufgabe der UN", "Es gibt keinen Unterschied", "Anpassung bedeutet, nichts zu tun"], r: 0, info: "Beides ist nötig: Ohne Klimaschutz wird die Anpassung irgendwann unbezahlbar." },
          { t: "paare", f: "Klimaschutz oder Anpassung? Ordne zu", p: [["Deiche erhöhen", "Anpassung"], ["Kohleausstieg", "Klimaschutz"], ["Hitzeaktionsplan für Senioren", "Anpassung"], ["Windräder und Solaranlagen bauen", "Klimaschutz"], ["Schwammstadt: Regen versickern lassen", "Anpassung"]] },
          { t: "wahl", f: "Was war das Kyoto-Protokoll von 1997?", a: ["Das erste Abkommen mit verbindlichen Reduktionszielen für Industrieländer", "Ein Verbot von Benzinautos in Japan", "Die Gründung des Weltklimarats", "Ein Abkommen zum Schutz der Wale"], r: 0, info: "Es trat 2005 in Kraft; die USA ratifizierten es nie, China hatte keine Verpflichtungen – deshalb folgte Paris 2015." },
          { t: "wahl", f: "Bis wann will Deutschland laut Klimaschutzgesetz klimaneutral sein?", a: ["2045", "2030", "2050", "2100"], r: 0, info: "Klimaneutral heißt: Es wird nicht mehr Treibhausgas ausgestoßen, als wieder gebunden wird. Die EU plant 2050." },
          { t: "wahl", f: "Wie viele Erden bräuchte man ungefähr, wenn alle Menschen so lebten wie in Deutschland?", a: ["Etwa drei", "Etwa eine", "Etwa zehn", "Etwa eine halbe"], r: 0, info: "Der ökologische Fußabdruck Deutschlands liegt bei rund 4,5 globalen Hektar pro Person – verfügbar sind etwa 1,6." },
          { t: "wahl", f: "Was unterscheidet Wetter von Klima?", a: ["Wetter ist der aktuelle Zustand, Klima der Durchschnitt über mindestens 30 Jahre", "Wetter gibt es nur in Europa, Klima weltweit", "Klima ist das Wetter im Sommer", "Wetter wird gemessen, Klima geschätzt"], r: 0, info: "Ein kalter Winter widerlegt den Klimawandel also nicht – entscheidend ist der langfristige Trend." },
          { t: "wahl", f: "Was unterscheidet den heutigen Klimawandel von den natürlichen Klimaänderungen der Erdgeschichte?", a: ["Er verläuft viel schneller und wird vom Menschen verursacht", "Er ist viel schwächer als frühere Veränderungen", "Er betrifft nur die Nordhalbkugel", "Er wird durch die Sonne allein verursacht"], r: 0, info: "Eiszeiten und Warmzeiten wechselten über Jahrtausende; heute verändert sich das Klima innerhalb weniger Jahrzehnte." },
          { t: "reihenfolge", f: "Bringe die Wirkungskette in die richtige Reihenfolge", items: ["Fossile Brennstoffe werden verbrannt", "Mehr CO2 gelangt in die Atmosphäre", "Der Treibhauseffekt verstärkt sich", "Die Erde erwärmt sich", "Gletscher und Eisschilde schmelzen", "Der Meeresspiegel steigt"] }
        ]
      },
      {
        id: "smart-global-cities",
        kapitel: K[7],
        titel: "Smart Cities und Global Cities",
        kurz: "Global City, Smart City, São Paulo, Favela, Segregation, Gated Community, Megastadt, Hitzeinsel, 15-Minuten-Stadt",
        erklaerung: "<p>Mehr als die Hälfte der Menschheit lebt in Städten, 2050 werden es etwa zwei Drittel sein. <b>Megastädte</b> haben über zehn Millionen Einwohner (Tokio, Delhi, Shanghai, São Paulo). <b>Global Cities</b> wie New York, London oder Tokio steuern die Weltwirtschaft: Dort sitzen Konzernzentralen, Börsen, große Banken und internationale Flughäfen.</p><p>In <b>São Paulo</b> liegen Lebenswelten dicht beieinander: bewachte Wohnanlagen (Gated Communities) neben <b>Favelas</b>, informellen Siedlungen ohne gesicherte Wasser- und Abwasserversorgung. Diese räumliche Trennung heißt <b>Segregation</b>. <b>Smart Cities</b> nutzen Sensoren und Daten, um Verkehr, Energie und Verwaltung zu steuern – etwa Parkplatzsuche oder Ampelschaltung. Kritiker warnen vor Überwachung und Abhängigkeit von Konzernen. Nachhaltige Städte setzen auf kurze Wege (15-Minuten-Stadt), Grünflächen gegen die urbane Hitzeinsel und bezahlbaren Wohnraum. Typischer Fehler: Megastadt und Global City gleichsetzen – Lagos ist riesig, aber keine Global City; Frankfurt ist klein, aber ein globaler Finanzplatz.</p>",
        aufgaben: [
          { t: "wahl", f: "Was ist eine Global City?", a: ["Eine Stadt, von der aus die Weltwirtschaft gesteuert wird: Konzernzentralen, Börsen, Banken", "Jede Stadt mit über zehn Millionen Einwohnern", "Eine Stadt mit vielen Touristen", "Eine Hauptstadt"], r: 0, info: "Beispiele sind New York, London und Tokio; auch Frankfurt gilt wegen der Börse und der EZB als Global City." },
          { t: "wahl", f: "Was ist eine Smart City?", a: ["Eine Stadt, die digitale Technik und Daten nutzt, um Verkehr, Energie und Verwaltung zu steuern", "Eine Stadt mit vielen Universitäten", "Eine Stadt ohne Autos", "Eine Stadt mit besonders intelligenten Einwohnern"], r: 0, info: "Beispiele: Sensoren melden freie Parkplätze, Straßenlaternen leuchten nur, wenn jemand kommt, Behördengänge laufen online." },
          { t: "wahl", f: "Welche Maßnahme ist typisch für eine Smart City?", a: ["Sensoren erfassen den Verkehr und schalten Ampeln passend", "Alle Hochhäuser werden abgerissen", "Das Internet wird abgeschaltet", "Fahrräder werden verboten"], r: 0, info: "Ziel ist, Staus, Energieverbrauch und Emissionen zu senken." },
          { t: "wahl", f: "Welche Kritik gibt es an Smart Cities?", a: ["Überwachung, Datenschutzprobleme und Abhängigkeit von Technikkonzernen", "Sie verbrauchen mehr Papier", "Sie sind zu laut", "Sie haben zu wenige Einwohner"], r: 0, info: "Wer die Daten einer Stadt besitzt, hat viel Macht – deshalb fordern viele, dass die Daten der Stadt selbst gehören." },
          { t: "eingabe", f: "Wie heißt die größte Stadt Südamerikas?", l: ["São Paulo", "Sao Paulo"], info: "Die Metropolregion São Paulo hat über 20 Millionen Einwohner." },
          { t: "wahl", f: "Was ist eine Favela?", a: ["Eine informelle Siedlung in brasilianischen Städten, oft ohne Baugenehmigung und sichere Versorgung", "Ein Einkaufszentrum", "Ein brasilianisches Hochhausviertel für Reiche", "Ein Stadtpark"], r: 0, info: "In Favelas leben Millionen Menschen; viele Siedlungen wurden inzwischen an Strom und Wasser angeschlossen." },
          { t: "wahl", f: "Was bedeutet Segregation in der Stadtgeographie?", a: ["Die räumliche Trennung von Bevölkerungsgruppen, z. B. Arm und Reich in verschiedenen Vierteln", "Der Abriss alter Gebäude", "Die Trennung von Wohnen und Arbeiten", "Der Bau von Umgehungsstraßen"], r: 0, info: "In São Paulo grenzen bewachte Wohnanlagen direkt an Favelas – getrennt durch Mauern." },
          { t: "wahl", f: "Was ist eine Gated Community?", a: ["Eine abgeschlossene, bewachte Wohnanlage mit Zugangskontrolle", "Ein Stadtteil ohne Straßen", "Eine Favela mit Zaun", "Ein öffentlicher Park mit Toren"], r: 0, info: "Wohlhabende ziehen sich aus Angst vor Kriminalität zurück – die Stadtgesellschaft trennt sich weiter." },
          { t: "wahl", f: "Wie groß ist der Anteil der Weltbevölkerung, der in Städten lebt?", a: ["Über die Hälfte, bis 2050 voraussichtlich etwa zwei Drittel", "Etwa ein Viertel", "Etwa 90 Prozent", "Etwa ein Zehntel"], r: 0, info: "Seit 2007 leben mehr Menschen in Städten als auf dem Land; das Wachstum findet vor allem in Asien und Afrika statt." },
          { t: "wahl", f: "Ab welcher Einwohnerzahl spricht man von einer Megastadt?", a: ["Über 10 Millionen", "Über 1 Million", "Über 5 Millionen", "Über 50 Millionen"], r: 0, info: "Weltweit gibt es über 30 Megastädte; in Deutschland keine einzige." },
          { t: "paare", f: "Ordne die Städte zu", p: [["Tokio", "Größte Metropolregion der Welt mit rund 37 Millionen Menschen"], ["Lagos", "Schnell wachsende Megastadt in Nigeria"], ["Singapur", "Stadtstaat und Vorreiter bei Smart-City-Technik"], ["Masdar City", "Geplante Ökostadt in Abu Dhabi"], ["Songdo", "Am Reißbrett geplante Smart City in Südkorea"]] },
          { t: "wahl", f: "Was ist Gentrifizierung?", a: ["Die Aufwertung eines Viertels, bei der steigende Mieten ärmere Bewohner verdrängen", "Der Bau einer neuen Siedlung am Stadtrand", "Die Umwandlung von Büros in Wohnungen", "Der Zuzug älterer Menschen"], r: 0, info: "Erst kommen Studierende und Künstler, dann Cafés und Sanierungen, am Ende können sich die alten Bewohner die Miete nicht mehr leisten." },
          { t: "wahl", f: "Was ist eine urbane Hitzeinsel?", a: ["Städte sind wärmer als das Umland, weil Beton und Asphalt Wärme speichern und Grün fehlt", "Ein Thermalbad in der Stadt", "Eine Insel vor der Küste einer Stadt", "Ein Stadtteil mit Fernwärme"], r: 0, info: "Nachts kann der Unterschied zum Umland über 5 Grad betragen – Bäume, Dachbegrünung und Wasserflächen helfen." },
          { t: "wahl", f: "Was meint die Idee der 15-Minuten-Stadt?", a: ["Alles Wichtige – Einkaufen, Schule, Arzt, Arbeit – ist in 15 Minuten zu Fuß oder mit dem Rad erreichbar", "Jeder Bus kommt alle 15 Minuten", "Die Stadt ist in 15 Minuten zu durchqueren", "Arbeitstage dauern nur 15 Stunden pro Woche"], r: 0, info: "Das Konzept wurde in Paris bekannt; es spart Verkehr und stärkt die Stadtviertel." },
          { t: "wahl", f: "Welche Herausforderung haben schnell wachsende Städte des Globalen Südens vor allem?", a: ["Wohnraum, Wasser, Abwasser, Verkehr und Arbeitsplätze für die Zuwanderer vom Land", "Zu wenig Einwohner", "Zu viele Parks", "Sinkende Mieten"], r: 0, info: "Viele Menschen arbeiten im informellen Sektor – ohne Vertrag, Versicherung oder Steuern." },
          { t: "reihenfolge", f: "Wie entwickelt sich eine Favela typischerweise? Bringe die Schritte in die richtige Reihenfolge", items: ["Menschen ziehen vom Land in die Stadt und finden keine bezahlbare Wohnung", "Sie bauen einfache Hütten auf freiem Land am Stadtrand oder an Hängen", "Die Siedlung verfestigt sich: Ziegelhäuser, erste Stromleitungen", "Die Stadt erkennt die Siedlung an und baut Wasser, Abwasser und Wege aus"] }
        ]
      },
      {
        id: "globalisierung-fallbeispiele",
        kapitel: K[9],
        titel: "Globalisierung konkret: Welthandel, Global Player, Tourismus",
        kurz: "Global Player, Containerschifffahrt, WTO, Exportland Deutschland, Produktionsverlagerung, Lieferkettengesetz, Overtourism, nachhaltiger Tourismus",
        erklaerung: "<p>Globalisierung heißt: Wirtschaft, Kultur, Politik und Kommunikation verflechten sich weltweit. Der <b>Welthandel</b> ist seit 1950 enorm gewachsen – vor allem dank Container (ab 1956), billiger Transporte, offener Grenzen (WTO) und des Internets. Deutschland gehört zu den größten Exportnationen; wichtigste Ausfuhrgüter sind Autos, Maschinen und Chemieprodukte, größter Abnehmer sind die USA.</p><p><b>Global Player</b> wie Volkswagen, Apple oder Nestlé produzieren dort, wo es am günstigsten ist, und verlagern Arbeitsplätze nach Osteuropa oder Asien. <b>Gewinner</b> sind Verbraucher mit billigen Produkten und viele Schwellenländer, <b>Verlierer</b> oft Beschäftigte in alten Industrieregionen und die Umwelt. Das deutsche Lieferkettengesetz (seit 2023) soll Menschenrechte in der Produktion sichern. Auch der <b>Tourismus</b> ist globalisiert: Er bringt Einkommen, aber in Venedig, Barcelona oder auf Mallorca auch überfüllte Altstädte und steigende Mieten (Overtourism). Nachhaltiger Tourismus, etwa in Dörfern in Laos, soll die Einheimischen beteiligen und Natur schonen. Typischer Fehler: Globalisierung nur als Wirtschaftsphänomen sehen – Musik, Essen, Serien und Klimawandel sind genauso global.</p>",
        aufgaben: [
          { t: "wahl", f: "Was ist ein Global Player?", a: ["Ein Konzern, der weltweit produziert, einkauft und verkauft", "Ein Profisportler mit internationalen Verträgen", "Ein Land mit großer Fläche", "Eine Hilfsorganisation"], r: 0, info: "Beispiele: Volkswagen, Apple, Nestlé, Samsung – oft mit Umsätzen größer als die Wirtschaftsleistung ganzer Staaten." },
          { t: "wahl", f: "Welches sind Deutschlands wichtigste Exportgüter?", a: ["Kraftfahrzeuge, Maschinen und Chemieprodukte", "Getreide und Fleisch", "Kohle und Stahl", "Kleidung und Schuhe"], r: 0, info: "Deutschland exportiert jährlich Waren im Wert von über 1,5 Billionen Euro." },
          { t: "wahl", f: "Welches Land ist der größte Abnehmer deutscher Exporte?", a: ["USA", "China", "Russland", "Türkei"], r: 0, info: "Seit 2015 sind die USA Exportziel Nummer eins, gefolgt von Frankreich und den Niederlanden." },
          { t: "wahl", f: "Warum hat der Container den Welthandel so stark wachsen lassen?", a: ["Genormte Container machen Umladen zwischen Schiff, Bahn und Lkw schnell und billig", "Container sind aus Gold", "Container fahren von allein", "Container brauchen keine Häfen"], r: 0, info: "Ein T-Shirt um die halbe Welt zu verschiffen kostet nur wenige Cent." },
          { t: "wahl", f: "Welcher Hafen ist der größte Containerhafen Europas?", a: ["Rotterdam", "Hamburg", "Marseille", "Lissabon"], r: 0, info: "Weltweit liegen die größten Häfen in Asien: Shanghai, Singapur, Ningbo." },
          { t: "wahl", f: "Was ist die WTO?", a: ["Die Welthandelsorganisation mit Sitz in Genf, die Regeln für den Welthandel aufstellt", "Eine weltweite Gewerkschaft", "Die Welttourismusorganisation", "Ein Zusammenschluss von Ölstaaten"], r: 0, info: "Die WTO wurde 1995 gegründet; sie soll Zölle abbauen und Handelsstreit schlichten." },
          { t: "eingabe", f: "Wie nennt man es, wenn ein Unternehmen seine Produktion ins kostengünstigere Ausland verlegt? (englischer Fachbegriff oder deutsch)", l: ["Offshoring", "Outsourcing", "Produktionsverlagerung", "Verlagerung"], info: "Offshoring meint die Verlagerung ins Ausland; Outsourcing die Vergabe an fremde Firmen – oft kommt beides zusammen vor." },
          { t: "wahl", f: "Warum verlagern Unternehmen Produktion nach Asien oder Osteuropa?", a: ["Niedrigere Löhne, weniger Auflagen und Nähe zu neuen Märkten", "Weil es dort mehr Rohöl gibt", "Weil die Transportwege kürzer sind", "Weil die EU es vorschreibt"], r: 0, info: "Umgekehrt holen manche Firmen Produktion zurück, wenn Transportkosten steigen oder Lieferketten reißen." },
          { t: "wahl", f: "Wer zählt häufig zu den Verlierern der Globalisierung?", a: ["Geringqualifizierte Beschäftigte in Industrieländern, deren Arbeitsplätze verlagert werden", "Verbraucher, die billige Elektronik kaufen", "Konzerne mit weltweitem Absatz", "Schwellenländer mit wachsender Industrie"], r: 0, info: "Auch die Umwelt und Arbeiter in Billiglohnländern ohne Schutz gehören zu den Verlierern." },
          { t: "wahl", f: "Was verlangt das deutsche Lieferkettengesetz (seit 2023)?", a: ["Große Unternehmen müssen Menschenrechte und Umweltschutz bei ihren Zulieferern prüfen", "Alle Waren müssen in Deutschland produziert werden", "Lieferungen dürfen höchstens drei Tage dauern", "Jede Lieferung braucht eine Zollgebühr"], r: 0, info: "Es gilt für Firmen ab 1.000 Beschäftigten; Kinderarbeit und Zwangsarbeit sollen so bekämpft werden." },
          { t: "wahl", f: "Was bedeutet Overtourism?", a: ["Zu viele Touristen belasten eine Stadt: Gedränge, Müll, steigende Mieten, Verdrängung der Einwohner", "Tourismus über den Wolken", "Reisen in mehr als zehn Länder pro Jahr", "Urlaub außerhalb der Saison"], r: 0, info: "Venedig verlangt seit 2024 an vielen Tagen Eintritt von Tagesgästen; Barcelona begrenzt Ferienwohnungen." },
          { t: "paare", f: "Ordne die Dimensionen der Globalisierung zu", p: [["Kulturell", "Gleiche Serien, Musik und Fast Food weltweit"], ["Ökonomisch", "Welthandel und weltweit tätige Konzerne"], ["Politisch", "UN, Klimakonferenzen, internationale Abkommen"], ["Ökologisch", "Klimawandel und Plastikmüll kennen keine Grenzen"], ["Digital", "Internet und soziale Medien verbinden Menschen in Echtzeit"]] },
          { t: "wahl", f: "Was wird mit dem Begriff „McDonaldisierung“ kritisiert?", a: ["Dass sich weltweit eine gleichförmige Konsumkultur ausbreitet und lokale Vielfalt verdrängt", "Dass Fast Food zu teuer ist", "Dass es zu wenige Restaurants gibt", "Dass Burger ungesund sind"], r: 0, info: "Gegenbewegungen betonen regionale Küche, Sprachen und Traditionen." },
          { t: "wahl", f: "Warum machte das Containerschiff „Ever Given“ 2021 Schlagzeilen?", a: ["Es blockierte sechs Tage lang den Suezkanal und zeigte, wie verletzlich Lieferketten sind", "Es war das erste Schiff mit Solarantrieb", "Es sank vor Rotterdam", "Es transportierte den ersten Impfstoff"], r: 0, info: "Über den Suezkanal laufen rund zwölf Prozent des Welthandels; Hunderte Schiffe stauten sich." },
          { t: "wahl", f: "Was kennzeichnet nachhaltigen Tourismus, zum Beispiel in Dörfern in Laos?", a: ["Die Einheimischen verdienen mit, Natur und Kultur werden geschont, Gäste übernachten bei Familien", "Große Hotelanlagen ausländischer Ketten", "Möglichst viele Besucher in kurzer Zeit", "Pauschalreisen mit Flug und All-inclusive"], r: 0, info: "Community-based Tourism heißt: Das Dorf entscheidet mit und behält das Geld vor Ort." },
          { t: "wahl", f: "Welcher Vorgang gehört zur kulturellen Globalisierung?", a: ["Ein koreanischer Popsong wird weltweit gestreamt", "Ein Konzern baut ein Werk in Mexiko", "Die UN beschließt eine Resolution", "Ein Containerschiff fährt nach Hamburg"], r: 0, info: "K-Pop, Anime oder Netflix-Serien zeigen, dass kulturelle Globalisierung nicht nur aus den USA kommt." },
          { t: "reihenfolge", f: "Der Weg eines T-Shirts: Bringe die Stationen in die richtige Reihenfolge", items: ["Baumwolle wird in den USA oder Indien angebaut", "Garn wird in der Türkei oder China gesponnen und gefärbt", "Das Shirt wird in Bangladesch genäht", "Es wird per Container nach Europa verschifft und verkauft", "Als Altkleid landet es in Ostafrika"] }
        ]
      },
      {
        id: "migration-flucht",
        kapitel: K[10],
        titel: "Migration und Flucht: Ursachen, Wege, Integration",
        kurz: "Weltbevölkerung 8 Milliarden, Bevölkerungspolitik, Push- und Pull-Faktoren, Flüchtling vs. Migrant, Asylrecht, Gastarbeiter, Integration, Fluchtursachen",
        erklaerung: "<p>Im November 2022 erreichte die Weltbevölkerung <b>acht Milliarden</b>; Indien ist seit 2023 das bevölkerungsreichste Land. Staaten betreiben <b>Bevölkerungspolitik</b>: China begrenzte 1980 bis 2015 die Kinderzahl, Frankreich fördert Familien. Am wirksamsten senkt Bildung für Mädchen die Geburtenrate.</p><p>Menschen verlassen ihre Heimat wegen <b>Push-Faktoren</b> (Krieg, Verfolgung, Armut, Dürre) und werden von <b>Pull-Faktoren</b> (Sicherheit, Arbeit, Familie) angezogen. Ein <b>Flüchtling</b> nach der Genfer Konvention von 1951 flieht vor Verfolgung; Migranten wandern aus anderen Gründen. Weltweit sind über 120 Millionen Menschen auf der Flucht, die meisten bleiben im eigenen Land oder in Nachbarstaaten. Deutschland ist seit den <b>Gastarbeitern</b> der 1950er und 60er Jahre Einwanderungsland; rund ein Viertel der Bevölkerung hat eine Einwanderungsgeschichte. Artikel 16a des Grundgesetzes garantiert politisch Verfolgten Asyl; die Dublin-Regeln bestimmen, welches EU-Land zuständig ist. <b>Integration</b> heißt Teilhabe – Sprache, Schule, Arbeit – ohne die eigene Herkunft aufgeben zu müssen. Typischer Fehler: Die meisten Geflüchteten kommen nach Europa – falsch, rund 70 Prozent bleiben in Nachbarländern.</p>",
        aufgaben: [
          { t: "wahl", f: "Was unterscheidet einen Flüchtling von einem Migranten?", a: ["Ein Flüchtling flieht vor Verfolgung oder Krieg, ein Migrant wandert z. B. wegen Arbeit oder Familie", "Flüchtlinge kommen per Schiff, Migranten per Flugzeug", "Migranten bleiben, Flüchtlinge kehren immer zurück", "Es gibt keinen Unterschied"], r: 0, info: "Die Genfer Flüchtlingskonvention von 1951 definiert, wer als Flüchtling Schutz bekommt." },
          { t: "wahl", f: "Welcher Artikel des Grundgesetzes garantiert politisch Verfolgten Asyl?", a: ["Artikel 16a", "Artikel 1", "Artikel 20", "Artikel 38"], r: 0, info: "Das Asylrecht wurde 1993 eingeschränkt: Wer über einen sicheren Drittstaat einreist, kann sich nicht darauf berufen." },
          { t: "wahl", f: "Welches sind typische Push-Faktoren für Migration?", a: ["Krieg, Verfolgung, Armut, Dürre", "Hohe Löhne und Sicherheit im Zielland", "Verwandte im Zielland", "Gute Universitäten im Zielland"], r: 0, info: "Push-Faktoren stoßen Menschen aus der Heimat weg, Pull-Faktoren ziehen sie ins Zielland." },
          { t: "eingabe", f: "Aus welchem Land kamen 2015 und 2016 die meisten Asylsuchenden nach Deutschland?", l: ["Syrien"], info: "Grund war der Bürgerkrieg seit 2011; insgesamt stellten 2015 und 2016 über 1,2 Millionen Menschen einen Asylantrag." },
          { t: "wahl", f: "Wie viele Menschen sind laut UNHCR weltweit auf der Flucht (Stand 2024)?", a: ["Über 120 Millionen", "Etwa 5 Millionen", "Etwa 30 Millionen", "Über eine Milliarde"], r: 0, info: "Eingerechnet sind Binnenvertriebene, die im eigenen Land geflohen sind – sie machen mehr als die Hälfte aus." },
          { t: "wahl", f: "Wo bleiben die meisten Geflüchteten?", a: ["Im eigenen Land oder in Nachbarstaaten", "In Deutschland", "In den USA", "In Australien"], r: 0, info: "Rund 70 Prozent leben in Nachbarländern wie der Türkei, dem Iran, Kolumbien oder Uganda." },
          { t: "wahl", f: "Was legt die Dublin-Verordnung der EU fest?", a: ["Für ein Asylverfahren ist in der Regel das EU-Land zuständig, in dem die Person zuerst eingereist ist", "Jedes EU-Land nimmt gleich viele Geflüchtete auf", "Asyl gibt es nur in Irland", "Geflüchtete dürfen das Land frei wählen"], r: 0, info: "Dadurch sind Länder an den Außengrenzen wie Italien oder Griechenland besonders belastet." },
          { t: "wahl", f: "Wer waren die „Gastarbeiter“?", a: ["Arbeitskräfte, die die Bundesrepublik ab 1955 aus Italien, später der Türkei und anderen Ländern anwarb", "Ausländische Studierende", "Deutsche, die im Ausland arbeiteten", "Saisonkräfte in der Landwirtschaft der DDR"], r: 0, info: "Man dachte, sie würden zurückkehren – viele blieben und holten ihre Familien nach." },
          { t: "wahl", f: "Was geschah mit der Anwerbung von Gastarbeitern im Jahr 1973?", a: ["Sie wurde wegen der Ölkrise gestoppt (Anwerbestopp)", "Sie wurde auf alle Länder ausgeweitet", "Sie begann erst", "Sie wurde auf die DDR übertragen"], r: 0, info: "Bis dahin waren rund 14 Millionen Menschen gekommen, etwa 11 Millionen kehrten zurück." },
          { t: "wahl", f: "Wie groß ist etwa der Anteil der Menschen mit Einwanderungsgeschichte in Deutschland?", a: ["Rund ein Viertel", "Rund 5 Prozent", "Rund die Hälfte", "Rund 2 Prozent"], r: 0, info: "Zählt man Kinder von Eingewanderten mit, kommt man auf etwa 30 Prozent; in Städten wie Frankfurt ist es mehr als die Hälfte." },
          { t: "paare", f: "Ordne die Begriffe zu", p: [["Integration", "Teilhabe an Sprache, Schule und Arbeit bei Erhalt der eigenen Herkunft"], ["Assimilation", "Vollständige Anpassung und Aufgabe der Herkunftskultur"], ["Segregation", "Getrenntes Nebeneinander ohne Kontakt"], ["Binnenvertriebene", "Flucht innerhalb des eigenen Landes"], ["Duldung", "Abschiebung ist vorübergehend ausgesetzt"]] },
          { t: "wahl", f: "Wann erreichte die Weltbevölkerung acht Milliarden Menschen?", a: ["Im November 2022", "Im Jahr 2000", "Im Jahr 2010", "Im Jahr 1999"], r: 0, info: "1999 waren es sechs Milliarden, 2011 sieben – das Wachstum verlangsamt sich inzwischen." },
          { t: "wahl", f: "Welches Land hat seit 2023 die meisten Einwohner?", a: ["Indien", "China", "USA", "Indonesien"], r: 0, info: "Indien hat über 1,4 Milliarden Einwohner; Chinas Bevölkerung schrumpft seit 2022." },
          { t: "wahl", f: "Was war die Ein-Kind-Politik?", a: ["China erlaubte von 1980 bis 2015 den meisten Familien nur ein Kind", "Indien verbot Familien mit mehr als einem Kind", "Frankreich zahlte Geld nur für das erste Kind", "Japan verbot Kindergärten"], r: 0, info: "Folgen sind heute eine rasch alternde Gesellschaft und ein Männerüberschuss." },
          { t: "wahl", f: "Welche Maßnahme senkt die Geburtenrate in Entwicklungsländern nachweislich am stärksten?", a: ["Bildung und Berufschancen für Mädchen und Frauen", "Verbote von Großfamilien", "Höhere Steuern", "Bau von Autobahnen"], r: 0, info: "Gebildete Frauen heiraten später, haben Zugang zu Verhütung und weniger Kinder, die dafür gesünder aufwachsen." },
          { t: "wahl", f: "Wie kann man Fluchtursachen bekämpfen?", a: ["Durch Friedenssicherung, Entwicklungszusammenarbeit, fairen Handel und Klimaschutz", "Durch höhere Zäune an den Grenzen", "Durch Verbote von Auswanderung", "Durch Abschaffung des Asylrechts"], r: 0, info: "Wer in seiner Heimat Sicherheit und Perspektive hat, muss nicht fliehen – das ist langfristig billiger als Grenzschutz." },
          { t: "reihenfolge", f: "Bringe die Schritte eines Asylverfahrens in Deutschland in die richtige Reihenfolge", items: ["Ankunft und Registrierung", "Unterbringung in einer Erstaufnahmeeinrichtung", "Asylantrag beim Bundesamt für Migration und Flüchtlinge (BAMF)", "Persönliche Anhörung zu den Fluchtgründen", "Entscheidung: Schutz, Duldung oder Ablehnung", "Bei Ablehnung: Klage vor dem Verwaltungsgericht möglich"] }
        ]
      }
    );
  }

  // ---------- Politik ----------
  const P = fach("politik");
