    kap(P, "medien-extremismus", K[8]);
    kap(P, "international", K[11]);
    P.themen.push(
      {
        id: "digitale-maerkte",
        kapitel: K[4],
        titel: "Marktplatz Internet und Zukunft der Arbeit",
        kurz: "Markt und Preis, Wirtschaftskreislauf, Online-Handel, Plattformen, Strukturwandel, Automatisierung, KI, Homeoffice, Fachkräftemangel, Montabaur",
        erklaerung: "<p>Ein <b>Markt</b> ist das Zusammentreffen von Angebot und Nachfrage; der Preis bildet sich dort, wo beide übereinstimmen. Im <b>Wirtschaftskreislauf</b> stellen Haushalte den Unternehmen Arbeit zur Verfügung und bekommen Einkommen, mit dem sie Güter kaufen. Der <b>Marktplatz Internet</b> verändert das: Online-Handel bietet Auswahl und Preisvergleich rund um die Uhr, Plattformen wie Amazon, Uber oder Airbnb vermitteln, ohne selbst zu produzieren – Innenstädte leiden unter Leerstand.</p><p>Auch die <b>Arbeit</b> wandelt sich: Vom Strukturwandel (Landwirtschaft, Industrie, heute rund 75 Prozent Dienstleistungen) über <b>Automatisierung</b> bis zur Künstlichen Intelligenz. Routinetätigkeiten in Lager, Buchhaltung oder Produktion fallen weg, neue Berufe in IT, Pflege und Technik entstehen. Homeoffice, lebenslanges Lernen und Fachkräftemangel prägen den Arbeitsmarkt. Das Buch zeigt am Beispiel <b>Montabaur</b>, wie ein Ort im ländlichen Westerwald dank ICE-Anschluss zum Dienstleistungsstandort mit Konzernzentrale (United Internet) wurde. Typischer Fehler: Automatisierung vernichtet nur Arbeit – historisch sind bisher mehr Jobs entstanden als verschwunden, aber andere.</p>",
        aufgaben: [
          { t: "wahl", f: "Was ist ein Markt im wirtschaftlichen Sinn?", a: ["Das Zusammentreffen von Angebot und Nachfrage – egal ob auf dem Wochenmarkt oder im Internet", "Nur ein Platz mit Ständen in der Stadt", "Ein Geschäft, das dem Staat gehört", "Eine Börse"], r: 0, info: "Märkte gibt es für Waren, Dienstleistungen, Arbeit und Kapital." },
          { t: "wahl", f: "Wie entsteht in der Marktwirtschaft der Preis?", a: ["Dort, wo Angebot und Nachfrage übereinstimmen (Gleichgewichtspreis)", "Der Staat legt ihn fest", "Die Hersteller einigen sich untereinander", "Die Kunden stimmen ab"], r: 0, info: "Ist ein Gut knapp und begehrt, steigt der Preis; gibt es zu viel davon, sinkt er." },
          { t: "wahl", f: "Welchen Vorteil hat der Online-Handel für Kunden?", a: ["Große Auswahl, Preisvergleich und Einkaufen rund um die Uhr", "Man kann die Ware vorher anfassen", "Es gibt nie Lieferkosten", "Die Beratung ist persönlicher"], r: 0, info: "Dazu kommt ein gesetzliches Widerrufsrecht von 14 Tagen bei Online-Käufen." },
          { t: "wahl", f: "Welche Folge hat der Online-Handel für viele Innenstädte?", a: ["Geschäfte schließen, Leerstand nimmt zu", "Die Mieten für Läden sinken auf null", "Es gibt mehr Parkplätze", "Mehr Menschen ziehen in die Innenstadt"], r: 0, info: "Städte reagieren mit Gastronomie, Kultur und Wohnungen in ehemaligen Kaufhäusern." },
          { t: "eingabe", f: "Im Wirtschaftskreislauf stellen Haushalte den Unternehmen Arbeitskraft zur Verfügung und erhalten dafür ___.", l: ["Lohn", "Einkommen", "Gehalt", "Lohn und Gehalt"], info: "Mit dem Einkommen kaufen die Haushalte Güter – so fließt das Geld zurück zu den Unternehmen." },
          { t: "wahl", f: "Was kennzeichnet eine digitale Plattform wie Uber oder Airbnb?", a: ["Sie vermittelt zwischen Anbietern und Kunden, ohne eigene Autos oder Wohnungen zu besitzen", "Sie stellt alle Produkte selbst her", "Sie gehört dem Staat", "Sie arbeitet ohne Gewinn"], r: 0, info: "Plattformen verdienen an Provisionen und Daten; Kritiker bemängeln fehlende soziale Absicherung der Anbieter." },
          { t: "wahl", f: "Welche Tätigkeiten sind von Automatisierung und KI besonders betroffen?", a: ["Routinetätigkeiten mit klaren Regeln, z. B. im Lager, in der Buchhaltung oder am Fließband", "Pflege und Erziehung", "Handwerk mit wechselnden Baustellen", "Kreative Berufe ohne feste Abläufe"], r: 0, info: "Je vorhersehbarer eine Aufgabe, desto leichter übernimmt sie eine Maschine oder ein Programm." },
          { t: "wahl", f: "Was ist Homeoffice?", a: ["Arbeiten von zu Hause aus, meist über Internet und Videokonferenz", "Ein Büro im Rathaus", "Eine Nebentätigkeit am Abend", "Ein Haushaltsplan für Familien"], r: 0, info: "Seit der Corona-Pandemie arbeitet etwa ein Viertel der Beschäftigten in Deutschland zumindest teilweise von zu Hause." },
          { t: "paare", f: "Ordne die Begriffe zur Zukunft der Arbeit zu", p: [["Automatisierung", "Maschinen übernehmen Arbeitsschritte"], ["Künstliche Intelligenz", "Programme lernen aus Daten und treffen Entscheidungen"], ["Plattformökonomie", "Apps vermitteln Aufträge zwischen Anbietern und Kunden"], ["Lebenslanges Lernen", "Weiterbildung während des gesamten Berufslebens"], ["Gig-Economy", "Kurzfristige Einzelaufträge statt fester Anstellung"]] },
          { t: "wahl", f: "Was versteht man unter Strukturwandel?", a: ["Die Verschiebung der Beschäftigung von Landwirtschaft über Industrie zu Dienstleistungen", "Den Umbau eines Fabrikgebäudes", "Den Wechsel der Regierung", "Die Änderung der Schulstruktur"], r: 0, info: "Das Ruhrgebiet ist ein Beispiel: Von Kohle und Stahl zu Hochschulen, Logistik und Dienstleistungen." },
          { t: "wahl", f: "In welchem Wirtschaftssektor arbeiten in Deutschland die meisten Menschen?", a: ["Im Dienstleistungssektor (rund drei Viertel)", "In der Industrie", "In der Landwirtschaft", "Im Bergbau"], r: 0, info: "Nur noch etwa ein Prozent arbeitet in der Landwirtschaft, rund ein Viertel in Industrie und Handwerk." },
          { t: "wahl", f: "Warum ist Montabaur im Westerwald ein Beispiel für einen modernen Dienstleistungsstandort im ländlichen Raum?", a: ["Der ICE-Bahnhof an der Strecke Köln–Frankfurt zog Unternehmen wie United Internet und ein Outlet-Center an", "Dort wurde ein großes Stahlwerk gebaut", "Dort liegt der größte Flughafen Deutschlands", "Dort wird besonders viel Landwirtschaft betrieben"], r: 0, info: "Gute Verkehrsanbindung ist ein harter Standortfaktor – sie kann einem kleinen Ort einen großen Schub geben." },
          { t: "wahl", f: "Was bedeutet Fachkräftemangel?", a: ["Für offene Stellen gibt es zu wenige ausreichend qualifizierte Bewerber", "Es gibt zu viele Bewerber für wenige Stellen", "Fachkräfte verdienen zu wenig", "Alle Fachkräfte arbeiten im Ausland"], r: 0, info: "Besonders betroffen sind Pflege, Handwerk, IT und Erziehung – auch weil die geburtenstarken Jahrgänge in Rente gehen." },
          { t: "eingabe", f: "Welche Organisation vertritt die Interessen der Arbeitnehmer gegenüber den Arbeitgebern?", l: ["Gewerkschaft", "Gewerkschaften"], info: "Beispiele sind IG Metall und ver.di; sie handeln Tarifverträge aus und können zum Streik aufrufen." },
          { t: "wahl", f: "Was ist ein typischer Interessengegensatz zwischen Arbeitgebern und Arbeitnehmern?", a: ["Arbeitnehmer wollen höhere Löhne und kürzere Arbeitszeiten, Arbeitgeber niedrige Kosten", "Beide wollen weniger Kunden", "Arbeitgeber wollen mehr Urlaub für alle", "Arbeitnehmer wollen längere Arbeitszeiten ohne Lohn"], r: 0, info: "In Tarifverhandlungen suchen beide Seiten einen Kompromiss – manchmal erst nach Streik." },
          { t: "wahl", f: "Welches Ziel steht für ein Unternehmen in der Marktwirtschaft meist im Mittelpunkt?", a: ["Gewinn zu erzielen", "Möglichst viele Mitarbeiter einzustellen", "Möglichst hohe Steuern zu zahlen", "Preise möglichst hoch zu halten, egal ob jemand kauft"], r: 0, info: "Daneben zählen Marktanteil, Image und zunehmend Nachhaltigkeit – ohne Gewinn überlebt aber kein Unternehmen." },
          { t: "reihenfolge", f: "Bringe den Ablauf einer Online-Bestellung in die richtige Reihenfolge", items: ["Produkt auswählen und bestellen", "Bezahlen (z. B. Rechnung, Karte oder Bezahldienst)", "Ware wird im Lager verpackt und versandt", "Lieferung an die Haustür oder Packstation", "14 Tage Widerrufsrecht: Rückgabe ohne Angabe von Gründen möglich"] }
        ]
      },
      {
        id: "daten-geschaeftsmodelle",
        kapitel: K[8],
        titel: "Digitale Geschäftsmodelle und Daten",
        kurz: "Kostenlose Apps, Werbung und Daten, Algorithmen, Cookies, DSGVO, Recht am eigenen Bild, Online-Petition, Hate Speech, Filterblase",
        erklaerung: "<p>Viele Apps kosten nichts – bezahlt wird mit <b>Daten</b> und Aufmerksamkeit. Soziale Netzwerke verdienen an <b>personalisierter Werbung</b>: Je mehr sie über dich wissen, desto gezielter die Anzeigen. <b>Algorithmen</b> entscheiden, was du im Feed siehst, und zeigen bevorzugt, was dich lange hält. Weitere Geschäftsmodelle sind Abos, Freemium (Grundversion gratis, Extras kosten) und In-App-Käufe.</p><p>Die <b>DSGVO</b> (Datenschutz-Grundverordnung, seit 2018) gibt dir Rechte: Auskunft, Löschung, Datensparsamkeit; in Deutschland dürfen Jugendliche erst ab 16 allein in die Datenverarbeitung durch Netzwerke einwilligen. Das <b>Recht am eigenen Bild</b> schützt vor ungefragten Fotos. Das Internet ist auch politisch: Online-Petitionen beim Bundestag (ab 50.000 Unterschriften öffentliche Anhörung), Kampagnen, Shitstorms. Beleidigung und Volksverhetzung sind online genauso strafbar wie offline. Typischer Fehler: „Ich habe nichts zu verbergen“ – es geht nicht um Geheimnisse, sondern darum, wer dich mit deinen Daten beeinflussen kann.</p>",
        aufgaben: [
          { t: "wahl", f: "Warum sind viele Apps und soziale Netzwerke kostenlos?", a: ["Sie finanzieren sich über Werbung und die Auswertung von Nutzerdaten", "Der Staat bezahlt sie", "Sie werden von Spenden getragen", "Sie machen absichtlich Verlust"], r: 0, info: "Faustregel: Wenn ein Produkt nichts kostet, bist du das Produkt – deine Aufmerksamkeit wird verkauft." },
          { t: "wahl", f: "Was ist personalisierte Werbung?", a: ["Anzeigen, die zu deinem Profil passen – Alter, Interessen, Klickverhalten", "Werbung mit deinem Namen im Briefkasten", "Werbung nur für Prominente", "Werbung ohne Bilder"], r: 0, info: "Ein Netzwerk weiß oft mehr über dich als deine Freunde: Standort, Suchanfragen, wie lange du ein Video ansiehst." },
          { t: "eingabe", f: "Wie heißt die EU-Verordnung, die seit 2018 den Datenschutz regelt? (Abkürzung)", l: ["DSGVO", "Datenschutz-Grundverordnung", "Datenschutzgrundverordnung"], info: "Die DSGVO gilt in allen EU-Ländern und auch für Konzerne aus den USA, wenn sie Daten von EU-Bürgern verarbeiten." },
          { t: "wahl", f: "Ab welchem Alter darf man in Deutschland ohne Zustimmung der Eltern in die Datenverarbeitung durch soziale Netzwerke einwilligen?", a: ["16 Jahre", "12 Jahre", "14 Jahre", "18 Jahre"], r: 0, info: "Die DSGVO erlaubt den Ländern 13 bis 16 Jahre; Deutschland hat sich für 16 entschieden." },
          { t: "wahl", f: "Was macht der Algorithmus eines sozialen Netzwerks?", a: ["Er wählt aus, welche Beiträge du in welcher Reihenfolge siehst – meist das, was dich am längsten hält", "Er löscht alle Werbung", "Er prüft jeden Beitrag auf Wahrheit", "Er zeigt alle Beiträge in zeitlicher Reihenfolge"], r: 0, info: "Deshalb verbreiten sich aufregende oder empörende Inhalte besonders schnell." },
          { t: "wahl", f: "Was gilt für Werbung durch Influencer?", a: ["Sie muss als Werbung gekennzeichnet werden", "Sie ist verboten", "Sie braucht keine Kennzeichnung, wenn sie ehrlich gemeint ist", "Nur Fernsehwerbung muss gekennzeichnet werden"], r: 0, info: "Schleichwerbung ist unzulässig – Gerichte haben Influencer dafür bereits verurteilt." },
          { t: "paare", f: "Ordne die Begriffe zu", p: [["Cookies", "Kleine Dateien, mit denen Webseiten dich wiedererkennen"], ["Tracking", "Verfolgen deines Verhaltens über viele Seiten hinweg"], ["Abo-Modell", "Regelmäßige Zahlung für Zugang zu Inhalten"], ["Freemium", "Grundversion gratis, Zusatzfunktionen kosten"], ["In-App-Kauf", "Kauf innerhalb einer App, z. B. Münzen oder Skins"]] },
          { t: "wahl", f: "Was passiert mit einer Online-Petition an den Bundestag, die 50.000 Unterschriften in vier Wochen erreicht?", a: ["Der Petitionsausschuss berät sie in einer öffentlichen Anhörung", "Sie wird automatisch Gesetz", "Der Bundestag muss darüber abstimmen", "Sie wird an die UN weitergeleitet"], r: 0, info: "Eine Petition ist eine Bitte oder Beschwerde an das Parlament; das Recht dazu steht in Artikel 17 des Grundgesetzes." },
          { t: "wahl", f: "Was ist ein Shitstorm?", a: ["Eine Welle öffentlicher Empörung im Netz gegen eine Person oder Firma", "Ein Computervirus", "Ein Werbeformat", "Ein Streik von Influencern"], r: 0, info: "Shitstorms können berechtigte Kritik sein, kippen aber oft in Beleidigungen und Drohungen." },
          { t: "wahl", f: "Sind Beleidigungen und Volksverhetzung in sozialen Netzwerken strafbar?", a: ["Ja, dieselben Gesetze gelten online wie offline", "Nein, im Internet gilt Meinungsfreiheit ohne Grenzen", "Nur, wenn man seinen echten Namen benutzt", "Nur bei mehr als 1.000 Followern"], r: 0, info: "Plattformen müssen gemeldete strafbare Inhalte löschen; Täter können angezeigt werden." },
          { t: "wahl", f: "Was besagt das Recht am eigenen Bild?", a: ["Fotos oder Videos von dir dürfen nicht ohne deine Einwilligung veröffentlicht werden", "Du darfst jedes Bild im Netz kostenlos nutzen", "Nur Prominente dürfen fotografiert werden", "Du darfst dich selbst nicht fotografieren"], r: 0, info: "Ausnahmen gibt es für Personen der Zeitgeschichte oder Menschen als Beiwerk, etwa in einer Menschenmenge." },
          { t: "wahl", f: "Was bedeutet das Prinzip der Datensparsamkeit?", a: ["Es dürfen nur die Daten erhoben werden, die für den Zweck wirklich nötig sind", "Daten sollen möglichst klein gespeichert werden", "Man darf nur einmal pro Tag Daten senden", "Daten müssen auf Papier gespeichert werden"], r: 0, info: "Eine Taschenlampen-App braucht keinen Zugriff auf deine Kontakte – das ist ein Warnsignal." },
          { t: "wahl", f: "Welches Recht gibt dir die DSGVO gegenüber Unternehmen?", a: ["Auskunft darüber, welche Daten über dich gespeichert sind, und Löschung", "Kostenlose Produkte", "Zugriff auf die Daten anderer Nutzer", "Ein eigenes Passwort für alle Dienste"], r: 0, info: "Auf Anfrage muss ein Unternehmen innerhalb eines Monats antworten." },
          { t: "wahl", f: "Wie schützt du deine Konten am besten?", a: ["Für jeden Dienst ein eigenes starkes Passwort und Zwei-Faktor-Anmeldung", "Ein Passwort für alles, damit du es nicht vergisst", "Passwort im Profil veröffentlichen", "Den Geburtstag als Passwort nutzen"], r: 0, info: "Wird ein Dienst gehackt, sind sonst alle deine Konten offen." },
          { t: "wahl", f: "Wie kann man politisch über das Internet Einfluss nehmen?", a: ["Petitionen, Kampagnen, Kontakt zu Abgeordneten, Organisation von Demonstrationen", "Nur durch Wahlen alle vier Jahre", "Gar nicht, das Internet ist unpolitisch", "Nur über Fernsehsender"], r: 0, info: "Fridays for Future wurde über soziale Medien groß – Mobilisierung ist heute schneller als je zuvor." },
          { t: "reihenfolge", f: "Wie entsteht eine Filterblase? Bringe die Schritte in die richtige Reihenfolge", items: ["Du klickst und likest bestimmte Inhalte", "Der Algorithmus lernt deine Vorlieben", "Er zeigt dir mehr vom Gleichen", "Andere Sichtweisen tauchen kaum noch auf", "Du hältst deine Sicht für die Meinung aller"] }
        ]
      },
      {
        id: "nahost-frieden",
        kapitel: K[11],
        titel: "Nahostkonflikt und Friedenssicherung",
        kurz: "Balfour-Erklärung, UN-Teilungsplan, Staatsgründung Israel 1948, Nakba, Sechstagekrieg, Jerusalem, Oslo, Zwei-Staaten-Lösung, Gaza, Blauhelme, Bundeswehr als Parlamentsarmee",
        erklaerung: "<p>Der <b>Nahostkonflikt</b> ist ein Streit um Land zwischen Israelis und Palästinensern mit über hundertjähriger Geschichte: 1917 versprachen die Briten eine „nationale Heimstätte“ für Juden in Palästina (Balfour-Erklärung), 1947 schlugen die UN eine Teilung in zwei Staaten vor, 1948 wurde Israel gegründet – für Palästinenser die <b>Nakba</b> (Katastrophe), weil rund 700.000 Menschen flohen oder vertrieben wurden. Im <b>Sechstagekrieg 1967</b> besetzte Israel Westjordanland, Gazastreifen, Ostjerusalem und Golanhöhen. <b>Jerusalem</b> ist Juden, Christen und Muslimen heilig und wird von beiden Seiten als Hauptstadt beansprucht; auch <b>Wasser</b> ist knapp und umkämpft.</p><p>Das Oslo-Abkommen 1993 brachte Hoffnung auf eine <b>Zwei-Staaten-Lösung</b>, die aber nicht umgesetzt wurde. Der Gazastreifen wird seit 2007 von der islamistischen Hamas kontrolliert; ihr Angriff vom 7. Oktober 2023 und der folgende Krieg haben den Konflikt weiter verschärft. Frieden sichern sollen die <b>Vereinten Nationen</b> (Sicherheitsrat, <b>Blauhelme</b>), Bündnisse wie die NATO und Verhandlungen. Die <b>Bundeswehr</b> ist eine Parlamentsarmee: Jedem Auslandseinsatz muss der Bundestag zustimmen. Typischer Fehler: Schuld nur einer Seite zuweisen – der Konflikt hat auf beiden Seiten Opfer, Ängste und berechtigte Ansprüche.</p>",
        aufgaben: [
          { t: "wahl", f: "Was war die Balfour-Erklärung von 1917?", a: ["Großbritannien unterstützte eine „nationale Heimstätte“ für das jüdische Volk in Palästina", "Die Gründung des Staates Israel", "Ein Friedensvertrag zwischen Ägypten und Israel", "Die Teilung Jerusalems"], r: 0, info: "Palästina war damals Teil des Osmanischen Reiches und kam nach dem Ersten Weltkrieg unter britische Verwaltung." },
          { t: "wahl", f: "Was sah der UN-Teilungsplan von 1947 vor?", a: ["Teilung Palästinas in einen jüdischen und einen arabischen Staat, Jerusalem unter internationaler Verwaltung", "Ein gemeinsamer Staat für alle", "Die Rückgabe an das Osmanische Reich", "Die Angliederung an Ägypten"], r: 0, info: "Die jüdische Seite stimmte zu, die arabischen Staaten lehnten ab – es folgte der erste Nahostkrieg." },
          { t: "wahl", f: "Wann wurde der Staat Israel gegründet?", a: ["Am 14. Mai 1948", "Am 2. November 1917", "Am 5. Juni 1967", "Am 13. September 1993"], r: 0, info: "Einen Tag später griffen mehrere arabische Staaten an; Israel gewann den Krieg und vergrößerte sein Gebiet." },
          { t: "wahl", f: "Was bezeichnen Palästinenser als „Nakba“?", a: ["Flucht und Vertreibung von rund 700.000 Palästinensern im Krieg von 1948", "Den Bau der Sperranlage im Westjordanland", "Den Sechstagekrieg", "Den Beginn der Intifada"], r: 0, info: "Nakba ist arabisch für „Katastrophe“; viele Nachkommen leben bis heute in Flüchtlingslagern." },
          { t: "wahl", f: "Welche Gebiete besetzte Israel im Sechstagekrieg 1967?", a: ["Westjordanland, Gazastreifen, Ostjerusalem, Golanhöhen und Sinai-Halbinsel", "Den Libanon und Syrien", "Jordanien", "Zypern"], r: 0, info: "Den Sinai gab Israel 1982 nach dem Friedensvertrag an Ägypten zurück." },
          { t: "eingabe", f: "Welche Stadt ist Juden, Christen und Muslimen heilig und wird von Israelis wie Palästinensern als Hauptstadt beansprucht?", l: ["Jerusalem"], info: "Dort liegen Klagemauer, Grabeskirche sowie Felsendom und Al-Aqsa-Moschee dicht beieinander." },
          { t: "paare", f: "Ordne die heiligen Orte in Jerusalem zu", p: [["Klagemauer", "Judentum: Rest der Mauer des Zweiten Tempels"], ["Grabeskirche", "Christentum: Ort von Kreuzigung und Grab Jesu"], ["Felsendom und Al-Aqsa-Moschee", "Islam: Ort der Himmelsreise Mohammeds"], ["Tempelberg (Haram asch-Scharif)", "Von Juden und Muslimen gleichermaßen beansprucht"]] },
          { t: "wahl", f: "Was wurde im Oslo-Abkommen 1993 vereinbart?", a: ["Gegenseitige Anerkennung von Israel und PLO und eine palästinensische Selbstverwaltung in Teilen der besetzten Gebiete", "Die sofortige Gründung eines palästinensischen Staates", "Die Rückgabe des Golan an Syrien", "Der Beitritt Israels zur EU"], r: 0, info: "Rabin und Arafat gaben sich im Weißen Haus die Hand; Rabin wurde 1995 von einem israelischen Extremisten ermordet." },
          { t: "wahl", f: "Was bedeutet Zwei-Staaten-Lösung?", a: ["Israel und ein unabhängiger palästinensischer Staat bestehen friedlich nebeneinander", "Israel teilt sich in zwei Staaten", "Palästina wird zwischen Jordanien und Ägypten aufgeteilt", "Ein gemeinsamer Staat mit zwei Hauptstädten"], r: 0, info: "Die meisten Staaten und die UN unterstützen diese Lösung; Streitpunkte sind Grenzen, Jerusalem, Siedlungen und Flüchtlinge." },
          { t: "wahl", f: "Warum ist Wasser im Nahen Osten ein Konfliktthema?", a: ["Wasser ist knapp; Jordan und Grundwasser müssen zwischen Israel, Palästinensern und Jordanien geteilt werden", "Weil es dort zu viel regnet", "Weil das Meer zu salzig ist", "Weil Wasser dort verboten ist"], r: 0, info: "Palästinenser im Westjordanland haben pro Kopf deutlich weniger Wasser zur Verfügung als Israelis." },
          { t: "wahl", f: "Was geschah am 7. Oktober 2023?", a: ["Die Hamas griff Israel an, tötete rund 1.200 Menschen und verschleppte Geiseln; danach begann der Krieg im Gazastreifen", "Israel und Palästina schlossen Frieden", "Ägypten eroberte den Gazastreifen", "Die UN erkannten Palästina als Mitglied an"], r: 0, info: "Der folgende Krieg forderte im Gazastreifen Zehntausende Tote und eine schwere humanitäre Krise." },
          { t: "wahl", f: "Wer kontrolliert den Gazastreifen seit 2007 politisch?", a: ["Die islamistische Hamas", "Die Palästinensische Autonomiebehörde unter der Fatah", "Ägypten", "Die Vereinten Nationen"], r: 0, info: "Die Hamas wird von EU und USA als Terrororganisation eingestuft; Israel und Ägypten kontrollieren die Grenzen." },
          { t: "wahl", f: "Was sind Blauhelme?", a: ["Soldaten aus UN-Mitgliedsstaaten, die im Auftrag der Vereinten Nationen den Frieden sichern", "Die Polizei Israels", "Feuerwehrleute der UN", "Eine Spezialeinheit der NATO"], r: 0, info: "Blauhelme dürfen Waffen meist nur zur Selbstverteidigung einsetzen; Beispiel ist die UNIFIL-Mission im Libanon." },
          { t: "wahl", f: "Welches UN-Organ beschließt Friedensmissionen und Sanktionen?", a: ["Der Sicherheitsrat", "Die Generalversammlung", "Der Internationale Gerichtshof", "Der Generalsekretär allein"], r: 0, info: "Die fünf ständigen Mitglieder USA, Russland, China, Großbritannien und Frankreich haben ein Vetorecht." },
          { t: "wahl", f: "Wer muss in Deutschland jedem bewaffneten Auslandseinsatz der Bundeswehr zustimmen?", a: ["Der Bundestag", "Der Bundespräsident", "Der Verteidigungsminister allein", "Der Bundesrat"], r: 0, info: "Die Bundeswehr ist eine Parlamentsarmee – das hat das Bundesverfassungsgericht 1994 entschieden." },
          { t: "eingabe", f: "Wie heißt das westliche Verteidigungsbündnis, in dem ein Angriff auf ein Mitglied als Angriff auf alle gilt (Artikel 5)?", l: ["NATO", "Nato", "Nordatlantikpakt"], info: "Artikel 5 wurde bisher nur einmal ausgerufen: nach den Anschlägen vom 11. September 2001." },
          { t: "reihenfolge", f: "Bringe die Ereignisse des Nahostkonflikts in die richtige Reihenfolge", items: ["1917: Balfour-Erklärung", "1947: UN-Teilungsplan", "1948: Gründung Israels und erster Nahostkrieg", "1967: Sechstagekrieg", "1993: Oslo-Abkommen", "2023: Angriff der Hamas und Krieg im Gazastreifen"] }
        ]
      }
    );
